echo "== weekly: segment | week | finished | with poisson RT prediction <= KO-3h"
psq -tc "with ev as (select f.id, f.kickoff_at, (c.provider_league_id in (2,39,140,78,61,135)) prio from core.fixtures f join core.competition_seasons cs on cs.id=f.competition_season_id join core.competitions c on c.id=cs.competition_id where f.kickoff_at >= '2026-09-21' and f.kickoff_at < '2026-10-19' and f.status_group='finished' and c.provider_league_id in (2,39,140,78,61,135))
select prio, date_trunc('week', kickoff_at)::date, count(*), count(*) filter (where exists (select 1 from models.predictions p join models.model_versions v on v.id=p.model_version_id join models.model_registry r on r.id=v.model_id and r.name='poisson' where p.fixture_id=ev.id and p.market_key='1X2' and p.selection='Home' and p.backtest_session_id is null and p.data_cutoff_ts <= ev.kickoff_at - interval '3 hours')), min(kickoff_at)::date from ev group by 1,2 order by 1,2"
echo "== first RT poisson prediction (any cutoff) for priority fixtures in window"
psq -tc "select min(p.data_cutoff_ts), min(p.created_at) from core.fixtures f join core.competition_seasons cs on cs.id=f.competition_season_id join core.competitions c on c.id=cs.competition_id join models.predictions p on p.fixture_id=f.id and p.market_key='1X2' and p.selection='Home' and p.backtest_session_id is null join models.model_versions v on v.id=p.model_version_id join models.model_registry r on r.id=v.model_id and r.name='poisson' where f.kickoff_at >= '2026-09-01' and f.kickoff_at < now() and c.provider_league_id in (2,39,140,78,61,135)"
